mapper.select:
SELECT DATE_FORMAT(bill_date, '%Y-%m') AS period,
customer_name AS customerName, COUNT(*) AS billCount, IFNULL(SUM(total_qty), 0) AS totalQty, IFNULL(SUM(total_amount_tax), 0) AS totalAmount FROM sal_delivery WHERE bill_status IN ('CHECKED','FINISHED') AND deleted = 0 AND bill_date BETWEEN #{startDate} AND #{endDate} AND customer_id = #{customerId}
AND customer_name LIKE CONCAT('%', #{customer}, '%')
GROUP BY customer_name , DATE_FORMAT(bill_date, '%Y-%m') ORDER BY period ASC, totalAmount DESC LIMIT #{limit}

